script:
frappe.ui.form.on('Orden de Venta', {

    deal(frm) {

        frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "CRM Deal",
                name: frm.doc.deal
            },
            callback(r) {

                let deal = r.message;

                frm.clear_table("products");

                (deal.products || []).forEach(p => {

                    let row = frm.add_child("products");

                    row.product_code = p.product_code;
                    row.product_name = p.product_name;
                    row.qty = p.qty;
                    row.rate = p.rate;
                    row.amount = p.amount;
                });

                frm.refresh_field("products");
            }
        });
    }
});
